def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0
    # Find background color (most common) and foreground color
    from collections import Counter
    colors = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in colors:
                colors[v] = 0
            colors[v] += 1

    # Find majority color (background)
    max_count = 0
    background = 0
    for color, count in colors.items():
        if count > max_count:
            max_count = count
            background = color

    # Find minority color(s)
    foreground = set()
    for color, count in colors.items():
        if color != background:
            foreground.add(color)

    # Build output grid
    result = [[0 for _ in range(w)] for _ in range(h)]

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == background:
                # Background becomes 3, unless it needs to stay
                result[r][c] = 3
            else:
                # Foreground keeps its value
                result[r][c] = v

    return result
